        .fps-panel {
          position: relative;
          width: min(420px, 86%);
          padding: 34px 28px 30px;
          border-radius: 22px;
          background: linear-gradient(180deg, #15151a 0%, #0e0e11 100%);
          border: 1px solid #232329;
          box-shadow: 0 24px 60px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.04);
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 22px;
        }
        .fps-scan-stage {
          position: relative;
          width: 132px;
          height: 148px;
          display: grid;
          place-items: center;
        }
        .fps-svg {
          position: relative;
          z-index: 2;
          width: 108px;
          height: 128px;
          color: var(--fps-color);
          filter: drop-shadow(0 0 10px color-mix(in srgb, var(--fps-color) 55%, transparent));
          opacity: .9;
        }
        .fps-svg path {
          fill: none;
          stroke: currentColor;
          stroke-width: 2.4;
          stroke-linecap: round;
        }
        /* Scan-Linie: wischt vertikal über den Abdruck */
        .fps-scanline {
          position: absolute;
          left: 6%;
          right: 6%;
          top: 12%;
          height: 2px;
          z-index: 3;
          border-radius: 999px;
          background: linear-gradient(90deg, transparent, var(--fps-color) 30%, #ffe9b0 50%, var(--fps-color) 70%, transparent);
          box-shadow: 0 0 12px var(--fps-color), 0 0 26px var(--fps-color);
          opacity: 0;
          pointer-events: none;
        }
        .fps-root.fps-scanning .fps-scanline {
          opacity: 1;
          animation: fps-sweep calc(var(--fps-sp) * 1.25s) ease-in-out infinite;
        }
        @keyframes fps-sweep {
          0%   { transform: translateY(0); }
          50%  { transform: translateY(96px); }
          100% { transform: translateY(0); }
        }
        /* Puls-Ringe um den Abdruck */
        .fps-ring {
          position: absolute;
          inset: 0;
          border-radius: 50%;
          border: 1px solid var(--fps-color);
          opacity: 0;
          pointer-events: none;
        }
        .fps-root.fps-scanning .fps-ring {
          animation: fps-pulse calc(var(--fps-sp) * 1.25s) ease-out infinite;
        }
        @keyframes fps-pulse {
          0%   { transform: scale(.86); opacity: .85; }
          100% { transform: scale(1.5); opacity: 0; }
        }
        /* Check-Draw beim Erfolg */
        .fps-check {
          position: absolute;
          inset: 0;
          display: grid;
          place-items: center;
          z-index: 4;
        }
        .fps-check svg {
          width: 84px;
          height: 84px;
          color: var(--fps-color);
          filter: drop-shadow(0 0 12px color-mix(in srgb, var(--fps-color) 70%, transparent));
        }
        .fps-check path {
          fill: none;
          stroke: currentColor;
          stroke-width: 5;
          stroke-linecap: round;
          stroke-linejoin: round;
          stroke-dasharray: 60;
          stroke-dashoffset: 60;
        }
        .fps-root.fps-success .fps-check path {
          animation: fps-draw calc(var(--fps-sp) * 0.5s) ease-out forwards;
        }
        @keyframes fps-draw {
          to { stroke-dashoffset: 0; }
        }
        .fps-status {
          font-family: var(--display, inherit);
          font-size: 13px;
          font-weight: 600;
          letter-spacing: .22em;
          text-transform: uppercase;
          color: var(--fps-color);
          min-height: 1.4em;
          text-align: center;
        }
        .fps-btn {
          appearance: none;
          cursor: pointer;
          width: 100%;
          padding: 15px 20px;
